def area(P):
    s=0
    for i in range(len(P)):
        x1,y1=P[i];x2,y2=P[(i+1)%len(P)]
        s+=x1*y2-x2*y1
    return abs(s)/2
def edges(P):
    return [round(math.dist(P[i],P[(i+1)%len(P)]),2) for i in range(len(P))]
